pub const CONCEPTS_DIR: &str = "concepts";
pub const DIRECTION_FILE: &str = "direction.json";
pub const MAX_IMAGES_PER_BATCH: u32 = 12;
pub const MAX_REFS: usize = 8;

/// The aspect ratio asked for in the prompt.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize, specta::Type)]
pub enum Aspect {
    #[default]
    #[serde(rename = "16:9")]
    Wide,
    #[serde(rename = "3:2")]
    Landscape,
    #[serde(rename = "1:1")]
    Square,
    #[serde(rename = "3:4")]
    Portrait,
    #[serde(rename = "9:16")]
    Tall,
}

impl Aspect {
    pub fn ratio(self) -> &'static str {
        match self {
            Aspect::Wide => "16:9",
            Aspect::Landscape => "3:2",
            Aspect::Square => "1:1",
            Aspect::Portrait => "3:4",
            Aspect::Tall => "9:16",
        }
    }

    /// The size the Image API is asked for: within its limits (sides a
    /// multiple of 16, at most 3:1) and close to this ratio.
    pub fn api_size(self) -> &'static str {
        match self {
            Aspect::Wide => "1536x864",
            Aspect::Landscape => "1536x1024",
            Aspect::Square => "1024x1024",
            Aspect::Portrait => "1152x1536",
            Aspect::Tall => "864x1536",
        }
    }

    fn shape(self) -> &'static str {
        match self {
            Aspect::Wide | Aspect::Landscape => "landscape",
            Aspect::Square => "square",
            Aspect::Portrait | Aspect::Tall => "portrait",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, specta::Type)]
#[serde(rename_all = "camelCase")]
pub struct ConceptImage {
    /// Relative to the project folder, for example
    /// `concepts/porch-at-dusk/porch-at-dusk_03.png`.
    pub file: String,
    pub index: u32,
    pub width: Option<u32>,
    pub height: Option<u32>,
    pub starred: bool,
    pub picked: bool,
    /// The copy in `refs/` once the image was sent there.
    pub ref_file: Option<String>,
    pub created_at: String,
    /// The object it shows, in a direction of object refs.
    pub title: Option<String>,
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize, specta::Type)]
#[serde(rename_all = "camelCase")]
pub struct Direction {
    /// The folder name under `concepts/`.
    pub id: String,
    pub name: String,
    pub prompt: String,
    /// Reference images as given: relative to the project folder or
    /// absolute.
    pub refs: Vec<String>,
    pub aspect: Aspect,
    pub images: Vec<ConceptImage>,
    pub created_at: String,
    pub updated_at: String,
    /// Object refs: the concept they were taken from, relative to the
    /// project folder. `None` for an ordinary direction.
    pub source: Option<String>,
    /// Object refs: what the objects become on the Board.
    pub kind: Option<AssetKind>,
    /// The brief turned the project's style board off.
    pub style_off: bool,
    /// The style board revision the latest batch carried, `None` when it
    /// carried none.
    pub style_revision: Option<u32>,
    /// Refs work for one asset: its other views, or clean copies of its
    /// refs. `None` for an ordinary direction.
    #[serde(default)]
    pub refs_job: Option<RefsJob>,
}

impl Direction {
    /// True for a direction of object refs, one titled image per object.
    pub fn is_objects(&self) -> bool {
        self.source.is_some()
    }
}

impl Direction {
    /// The index the next image gets.
    pub fn next_index(&self) -> u32 {
        self.images.iter().map(|i| i.index).max().unwrap_or(0) + 1
    }
}

/// What the Lab's composer (or an agent) asks for.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, specta::Type)]
#[serde(rename_all = "camelCase")]
pub struct NewConcepts {
    pub project: String,
    /// The direction's name. An existing direction with the same name gets
    /// more images.
    pub direction: String,
    pub prompt: String,
    pub refs: Vec<String>,
    pub aspect: Aspect,
    pub count: u32,
    /// Whether the jobs carry the project's style board. On unless the
    /// brief turns it off; an empty board carries nothing either way.
    #[serde(default = "style_on")]
    pub use_style: bool,
}

pub(crate) fn style_on() -> bool {
    true
}

/// Serialises writes to `direction.json` files: jobs finish on their own
/// threads, and the UI marks images at the same time.
static WRITES: Mutex<()> = Mutex::new(());

fn write_lock() -> std::sync::MutexGuard<'static, ()> {
    WRITES.lock().unwrap_or_else(|p| p.into_inner())
}

/// The highest image index handed out per direction folder. A batch's
/// files only appear once Codex saves them, so two batches prepared before
/// either lands would otherwise both start at the same index and one image
/// would overwrite the other. Only touched under the write lock.
static RESERVED: Mutex<BTreeMap<PathBuf, u32>> = Mutex::new(BTreeMap::new());

pub fn concepts_dir(project_dir: &Path) -> PathBuf {
    project_dir.join(CONCEPTS_DIR)
}

fn check_direction_id(id: &str) -> CoreResult<()> {
    if crate::workspace::is_single_segment(id) && !id.starts_with('.') {
        Ok(())
    } else {
        Err(CoreError::Invalid(format!("{id:?} is not a direction id.")))
    }
}

pub fn direction_dir(project_dir: &Path, id: &str) -> CoreResult<PathBuf> {
    check_direction_id(id)?;
    Ok(concepts_dir(project_dir).join(id))
}

/// The direction stored in `concepts/<id>/`, or `None` when there is none.
pub fn load_direction(project_dir: &Path, id: &str) -> CoreResult<Option<Direction>> {
    let path = direction_dir(project_dir, id)?.join(DIRECTION_FILE);
    match fs::read_to_string(&path) {
        Ok(text) => from_json_with_defaults::<Direction>(&text)
            .map(Some)
            .map_err(|e| CoreError::json(&path, e)),
        Err(err) if err.kind() == io::ErrorKind::NotFound => Ok(None),
        Err(err) => Err(CoreError::io(&path, err)),
    }
}

fn save_direction(project_dir: &Path, direction: &Direction) -> CoreResult<()> {
    let dir = direction_dir(project_dir, &direction.id)?;
    fs::create_dir_all(&dir).map_err(|e| CoreError::io(&dir, e))?;
    write_json(&dir.join(DIRECTION_FILE), direction)
}

/// Loads, changes and writes back one direction under the write lock.
pub fn modify_direction<T>(
    project_dir: &Path,
    id: &str,
    change: impl FnOnce(&mut Direction) -> CoreResult<T>,
) -> CoreResult<(Direction, T)> {
    let _guard = write_lock();
    let mut direction = load_direction(project_dir, id)?
        .ok_or_else(|| CoreError::NotFound(format!("the direction {id}")))?;
    let out = change(&mut direction)?;
    direction.updated_at = now_rfc3339();
    save_direction(project_dir, &direction)?;
    Ok((direction, out))
}

/// Every direction of the project, the most recently changed first.
/// Folders without a readable `direction.json` are skipped.
pub fn list_directions(project_dir: &Path) -> Vec<Direction> {
    let Ok(entries) = fs::read_dir(concepts_dir(project_dir)) else {
        return Vec::new();
    };
    let mut out: Vec<Direction> = entries
        .flatten()
        .filter(|e| e.path().is_dir())
        .filter_map(|e| {
            let id = e.file_name().to_string_lossy().into_owned();
            if crate::workspace::sync::is_sync_name(&id) {
                return None;
            }
            load_direction(project_dir, &id).ok().flatten()
        })
        .collect();
    out.sort_by(|a, b| b.updated_at.cmp(&a.updated_at).then(a.name.cmp(&b.name)));
    out
}

/// Checks a request and returns it cleaned (trimmed text, refs kept to
/// files that exist).
pub fn clean_request(project_dir: &Path, new: &NewConcepts) -> CoreResult<NewConcepts> {
    let direction = new.direction.trim();
    if direction.is_empty() {
        return Err(CoreError::Invalid("Name the direction.".to_string()));
    }
    if direction.chars().count() > 60 {
        return Err(CoreError::Invalid(
            "Keep the direction name to 60 characters or fewer.".to_string(),
        ));
    }
    let prompt = new.prompt.trim();
    if prompt.is_empty() {
        return Err(CoreError::Invalid(
            "Describe what the concepts should show.".to_string(),
        ));
    }
    if !(1..=MAX_IMAGES_PER_BATCH).contains(&new.count) {
        return Err(CoreError::Invalid(format!(
            "Ask for between 1 and {MAX_IMAGES_PER_BATCH} images."
        )));
    }
    if new.refs.len() > MAX_REFS {
        return Err(CoreError::Invalid(format!(
            "Attach {MAX_REFS} reference images at most."
        )));
    }
    let mut refs = Vec::new();
    for r in &new.refs {
        let r = r.trim();
        if r.is_empty() || refs.iter().any(|x: &String| x == r) {
            continue;
        }
        let path = resolve_ref(project_dir, r);
        if !path.is_file() {
            return Err(CoreError::NotFound(format!("the reference image {r}")));
        }
        refs.push(r.to_string());
    }
    Ok(NewConcepts {
        project: new.project.clone(),
        direction: direction.to_string(),
        prompt: prompt.to_string(),
        refs,
        aspect: new.aspect,
        count: new.count,
        use_style: new.use_style,
    })
}

/// A reference as an absolute path.
pub fn resolve_ref(project_dir: &Path, reference: &str) -> PathBuf {
    let path = Path::new(reference);
    if path.is_absolute() {
        path.to_path_buf()
    } else {
        project_dir.join(path)
    }
}

/// Creates the direction, or refreshes the brief of an existing one with
/// the same name, and returns it with the files the new images go to
/// (relative to the project folder) and their indexes. The indexes are
/// reserved, so a batch prepared at the same moment gets the next ones.
pub fn prepare(
    project_dir: &Path,
    new: &NewConcepts,
) -> CoreResult<(Direction, Vec<(u32, String)>)> {
    prepare_with(project_dir, new, None)
}

/// [`prepare`] for a batch that carries the style board at
/// `style_revision`, which the direction records.
pub(crate) fn prepare_with(
    project_dir: &Path,
    new: &NewConcepts,
    style_revision: Option<u32>,
) -> CoreResult<(Direction, Vec<(u32, String)>)> {
    let id = slugify(&new.direction);
    let folder = direction_dir(project_dir, &id)?;
    let _guard = write_lock();
    let now = now_rfc3339();
    let existing = load_direction(project_dir, &id)?;
    let fresh = existing.is_none();
    let mut direction = existing.unwrap_or_else(|| Direction {
        id: id.clone(),
        created_at: now.clone(),
        ..Direction::default()
    });
    direction.name.clone_from(&new.direction);
    direction.prompt.clone_from(&new.prompt);
    direction.refs.clone_from(&new.refs);
    direction.aspect = new.aspect;
    direction.style_off = !new.use_style;
    direction.style_revision = style_revision;
    direction.updated_at = now;
    save_direction(project_dir, &direction)?;
    let mut reserved = RESERVED.lock().unwrap_or_else(|p| p.into_inner());
    // A direction made afresh numbers from 1 again.
    let taken = if fresh {
        0
    } else {
        reserved.get(&folder).copied().unwrap_or(0)
    };
    let first = direction
        .next_index()
        .max(next_free_index(project_dir, &id))
        .max(taken + 1);
    reserved.insert(folder, first + new.count - 1);
    let files = (first..first + new.count)
        .map(|index| (index, format!("{CONCEPTS_DIR}/{id}/{id}_{index:02}.png")))
        .collect();
    Ok((direction, files))
}

/// One past the highest `<id>_<n>.png` already in the folder, so a job
/// that is still running (or a file left by a failed one) is never
/// overwritten by the next batch.
fn next_free_index(project_dir: &Path, id: &str) -> u32 {
    let Ok(entries) = fs::read_dir(concepts_dir(project_dir).join(id)) else {
        return 1;
    };
    let prefix = format!("{id}_");
    entries
        .flatten()
        .filter_map(|e| {
            let name = e.file_name().to_string_lossy().into_owned();
            name.strip_prefix(&prefix)?
                .strip_suffix(".png")?
                .parse::<u32>()
                .ok()
        })
        .max()
        .map_or(1, |n| n + 1)
}

/// Records a finished image in its direction.
pub fn add_image(
    project_dir: &Path,
    direction: &str,
    index: u32,
    file: &str,
    title: Option<&str>,
) -> CoreResult<Direction> {
    let (width, height) = fs::read(project_dir.join(file))
        .ok()
        .and_then(|bytes| crate::inbox::images::dimensions(&bytes))
        .map_or((None, None), |(w, h)| (Some(w), Some(h)));
    let (direction, ()) = modify_direction(project_dir, direction, |d| {
        d.images.retain(|i| i.file != file);
        d.images.push(ConceptImage {
            file: file.to_string(),
            index,
            width,
            height,
            starred: false,
            picked: false,
            ref_file: None,
            created_at: now_rfc3339(),
            title: title.map(str::to_string),
        });
        d.images.sort_by_key(|i| i.index);
        Ok(())
    })?;
    Ok(direction)
}

/// Stars or picks an image (only the marks that are `Some` change).
pub fn mark(
    project_dir: &Path,
    direction: &str,
    file: &str,
    starred: Option<bool>,
    picked: Option<bool>,
) -> CoreResult<Direction> {
    let (direction, ()) = modify_direction(project_dir, direction, |d| {
        let image = d
            .images
            .iter_mut()
            .find(|i| i.file == file)
            .ok_or_else(|| CoreError::NotFound(format!("the concept {file}")))?;
        if let Some(starred) = starred {
            image.starred = starred;
        }
        if let Some(picked) = picked {
            image.picked = picked;
        }
        Ok(())
    })?;
    Ok(direction)
}

